// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber) public {
        // Ensure timestamp > initial pastBlockTime (0) and set block context
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // Call fallback with 10 ether
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // The reference sets pastBlockTime = block.timestamp after the require
        // If call succeeds, pastBlockTime must equal timestamp
        if (success) {
            assertTrue(c.pastBlockTime() == timestamp);
        }
        // If call fails (e.g., timestamp <= pastBlockTime), not relevant to property
    }
}

